using DobleCommander;

static class AutomaticTests {
 static int passed;
 static void Assert(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 static T Pump<T>(Task<T> task){Pump((Task)task);return task.GetAwaiter().GetResult();}
 static void Pump(Task task){var until=DateTime.UtcNow.AddSeconds(40);while(!task.IsCompleted){if(DateTime.UtcNow>until)throw new Exception("Timeout");Application.DoEvents();Thread.Sleep(1);}task.GetAwaiter().GetResult();}
 static IEnumerable<Control> Children(Control c){yield return c;foreach(Control child in c.Controls)foreach(var nested in Children(child))yield return nested;}
 static Task DropOnDestinations(LiteWindow form,string path){var data=new DataObject(DataFormats.FileDrop,new[]{path});var args=new DragEventArgs(data,0,0,0,DragDropEffects.Copy,DragDropEffects.Copy);var list=Children(form).OfType<DeviceList>().Single();typeof(Control).GetMethod("OnDragDrop",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(list,new object[]{args});return form.LastDropOperation;}
 [STAThread] static int Main(string[] args){
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());
  var root=Path.Combine(Path.GetTempPath(),"Rcopies-auto-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{
   string Dir(string name){var path=Path.Combine(root,name);Directory.CreateDirectory(path);return path;}
   void Write(string folder,string name,string content){var full=Path.Combine(folder,name);Directory.CreateDirectory(Path.GetDirectoryName(full)!);File.WriteAllText(full,content);}
   StorageUnit? Unit(string path)=>path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)?new(path,Path.GetFileName(path),DriveType.Removable,1_000_000_000_000,900_000_000_000,"NTFS"):null;
   string source=Dir("source-volume/Carpeta de trabajo 11-08-2026"),a=Path.Combine(root,"UNIDAD-A"),b=Path.Combine(root,"UNIDAD-B");var folder=Path.GetFileName(source);
   Write(source,"actualizado.txt","Original");Write(source,"borrado.txt","To be removed later");Directory.CreateDirectory(Path.Combine(source,"Vacia"));
   using(var form=new LiteWindow(false,Dir("logs"),Unit,()=>true)){
    Assert(Children(form).OfType<Button>().All(button=>!button.Text.Contains("Espejo",StringComparison.OrdinalIgnoreCase)),"there is no manual Espejo button");
    Assert(!Children(form).OfType<CheckBox>().Single(box=>box.Text=="Solo contenido").Checked,"folder name is preserved by default");
    form.AddPaths([a]);int confirmations=0;form.AutomaticConfirmation=previews=>{confirmations++;return Task.FromResult<AutomaticMirrorApproval?>(new(previews,false));};
    Pump(form.SelectSourceFromUiAsync(source));Assert(!Directory.Exists(a)&&confirmations==0,"choosing a new source without a matching folder only prepares normal copy");
    Pump(form.HandleDropAsync([source]));Assert(File.Exists(Path.Combine(a,folder,"actualizado.txt"))&&!File.Exists(Path.Combine(a,"actualizado.txt"))&&confirmations==0,"drop starts first copy and preserves the named source folder");
    Write(a,"Fuera-del-espejo.txt","Must remain untouched");Write(source,"actualizado.txt","Updated version with new data");File.Delete(Path.Combine(source,"borrado.txt"));Write(source,"nuevo.txt","New");
    var before=MirrorPlanner.Scan(a);form.AddPaths([b]);
    form.AutomaticConfirmation=previews=>{confirmations++;Assert(previews.Length==1&&previews[0].Destination==Path.Combine(a,folder),"automatic comparison is scoped to the matching named folder");Assert(MirrorPlanner.Same(before,MirrorPlanner.Scan(a))&&!Directory.Exists(b),"confirmation occurs before any mirror or normal destination changes");return Task.FromResult<AutomaticMirrorApproval?>(null);};
    Pump(form.SelectSourceFromUiAsync(source));Assert(confirmations==1&&File.Exists(Path.Combine(a,folder,"borrado.txt"))&&!Directory.Exists(b),"cancelling automatic mirror also prevents copies to fresh units");Assert(form.ProgressSummary==""&&form.GlobalProgress==0&&form.Targets.All(row=>!row.ShowProgress),"cancelled automatic confirmation clears all progress information");
    MirrorPreview[]? pending=null;form.AutomaticConfirmation=previews=>{confirmations++;pending=previews;return Task.FromResult<AutomaticMirrorApproval?>(new(previews,false));};
    Pump(form.SelectSourceFromUiAsync(source));Assert(confirmations==2&&File.ReadAllText(Path.Combine(a,folder,"actualizado.txt"))==File.ReadAllText(Path.Combine(source,"actualizado.txt"))&&!File.Exists(Path.Combine(a,folder,"borrado.txt"))&&File.Exists(Path.Combine(a,folder,"nuevo.txt")),"choosing an existing source automatically applies confirmed updates, adds and deletes");
    Assert(File.Exists(Path.Combine(a,"Fuera-del-espejo.txt"))&&File.Exists(Path.Combine(b,folder,"nuevo.txt")),"mixed mirror/copy operation preserves unrelated root data and copies the named folder to fresh units");
    Assert(form.Targets.Single(row=>row.Path==a).Mirror?.Destination==Path.Combine(a,folder)&&form.Targets.Single(row=>row.Path==b).Copy!=null&&form.GlobalProgress==100,"nested mirrors and root copy jobs map to their original unit rows and complete globally");
    form.AutomaticConfirmation=_=>throw new Exception("Unchanged folders must not prompt");Pump(form.HandleDropAsync([source]));Assert(form.ProgressSummary==""&&confirmations==2,"identical matching folders are skipped without confirmation or copy");
    Write(source,"actualizado.txt","Another update for a drag");form.AutomaticConfirmation=previews=>{confirmations++;return Task.FromResult<AutomaticMirrorApproval?>(new(previews,false));};Pump(DropOnDestinations(form,source));Assert(confirmations==3&&form.Targets.Count(row=>row.Mirror!=null)==2&&form.Targets.Where(row=>row.Mirror!=null).All(row=>row.Mirror!.Status.State=="Completado"),"actual DragDrop event detects and confirms matching folders across multiple units");
    var current=Pump(AutomaticMirrorPlanner.AnalyzeAsync(source,[a,b],false));Assert(current.ChangedMirrors.Length==0&&current.NewDestinations.Length==0&&current.UnchangedFolders.Length==2,"analysis distinguishes unchanged matching folders from fresh roots");
    Write(source,"actualizado.txt","Source-area change awaiting approval");form.AutomaticConfirmation=_=>{confirmations++;return Task.FromResult<AutomaticMirrorApproval?>(null);};Pump(form.HandleDropAsync([source],true));Assert(confirmations==4&&File.ReadAllText(Path.Combine(a,folder,"actualizado.txt"))=="Another update for a drag","dropping onto the source area also compares matching folders and preserves data on cancellation");
    Write(source,"actualizado.txt","Partial update");Write(source,"nuevo.txt","Excluded update should remain old");var oldNew=File.ReadAllText(Path.Combine(a,folder,"nuevo.txt"));form.SelectTarget(b,false);
    form.AutomaticConfirmation=previews=>Task.FromResult<AutomaticMirrorApproval?>(new(previews.Select(p=>MirrorPlanner.SelectChanges(p,new HashSet<string>{"actualizado.txt"})).ToArray(),false));Pump(form.StartCopyAsync());Assert(File.ReadAllText(Path.Combine(a,folder,"actualizado.txt"))=="Partial update"&&File.ReadAllText(Path.Combine(a,folder,"nuevo.txt"))==oldNew,"automatic confirmation retains the previous per-file partial synchronization controls");
    var request=Pump(AutomaticMirrorPlanner.AnalyzeAsync(source,[a],false));using(var popup=new MirrorConfirmationDialog(request.ChangedMirrors,true,1)){
     Assert(popup.Text=="Por favor confirme el proceso de espejo"&&Children(popup).OfType<Label>().Any(label=>label.Text.Contains("Los destinos tienen datos que han sido actualizados en el origen")),"automatic popup contains the exact requested confirmation and explanation");Assert(Children(popup).OfType<Button>().Select(button=>button.Text).Order().SequenceEqual(new[]{"Cancelar","Proceder"}),"automatic popup has only Proceder and Cancelar as final actions");
     if(args.Length==2&&args[0]=="--render"){popup.Show();Application.DoEvents();using var image=new Bitmap(popup.Width,popup.Height);popup.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(args[1],System.Drawing.Imaging.ImageFormat.Png);popup.Close();}
    }
   }
   var file=Path.Combine(source,"actualizado.txt");var fileTarget=Path.Combine(root,"FILE-UNIT");using(var form=new LiteWindow(false,Dir("file-logs"),Unit,()=>true)){form.AddPaths([fileTarget]);form.AutomaticConfirmation=_=>throw new Exception("Files must not trigger folder mirrors");Pump(form.HandleDropAsync([file]));Assert(File.ReadAllText(Path.Combine(fileTarget,"actualizado.txt"))==File.ReadAllText(file),"individual files retain automatic normal copying without a mirror prompt");}
   var conflict=Dir("FILE-CONFLICT");Write(conflict,folder,"Not a folder");bool rejected=false;try{Pump(AutomaticMirrorPlanner.AnalyzeAsync(source,[conflict],false));}catch(IOException){rejected=true;}Assert(rejected&&File.ReadAllText(Path.Combine(conflict,folder))=="Not a folder","same-name file collisions are rejected without overwriting data");
   using(var form=new LiteWindow(false,Dir("free-logs"),Unit,()=>false)){form.SetSource(source);form.AddPaths([a,b]);int calls=0;form.AutomaticConfirmation=_=>{calls++;return Task.FromResult<AutomaticMirrorApproval?>(null);};rejected=false;try{Pump(form.StartCopyAsync());}catch(IOException){rejected=true;}Assert(rejected&&calls==0,"free license limit is checked before comparison confirmation or writes");}
   using(var token=new CancellationTokenSource()){token.Cancel();rejected=false;try{Pump(AutomaticMirrorPlanner.AnalyzeAsync(source,[a],false,token:token.Token));}catch(OperationCanceledException){rejected=true;}Assert(rejected,"automatic analysis honors cancellation before traversal");}
   string emptySource=Dir("empty-volume/EmptyWork"),emptyUnit=Dir("EMPTY-UNIT");Write(emptyUnit,"EmptyWork/Old.txt","Must survive cancelled empty mirror");Write(emptyUnit,"Outside.txt","Outside scope");using(var form=new LiteWindow(false,Dir("empty-logs"),Unit,()=>true)){form.AddPaths([emptyUnit]);form.AutomaticConfirmation=previews=>{using var popup=new MirrorConfirmationDialog(previews,true);Assert(Children(popup).OfType<Label>().Any(label=>label.Text.Contains("el origen no contiene archivos")),"empty source warning is shown before automatic deletion of an existing named folder");return Task.FromResult<AutomaticMirrorApproval?>(null);};Pump(form.SelectSourceFromUiAsync(emptySource));Assert(File.Exists(Path.Combine(emptyUnit,"EmptyWork","Old.txt"))&&File.Exists(Path.Combine(emptyUnit,"Outside.txt")),"cancelling an empty-source mirror preserves both matching and unrelated data");}
   Console.WriteLine($"{passed} automatic named-folder mirror assertions passed. Temporary test units only.");return 0;
  }catch(Exception error){Console.Error.WriteLine(error);return 1;}finally{Directory.Delete(root,true);}
 }
}
